text:
{
  "initiative": "Improve first-contact resolution to 95% in the support organisation",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Baseline assessment and process mapping",
      "owner_role": "Support Process Analyst",
      "duration_quarters": 1,
      "deliverable": "Baseline report with current FCR rate, root-cause analysis of top causes, and mapped contact-handling process"
    },
    {
      "id": "WP-02",
      "title": "Knowledge base and tooling improvements",
      "owner_role": "Knowledge Engineering Lead",
      "duration_quarters": 2,
      "deliverable": "Deployed knowledge base and tooling changes that enable self-service and reduce support requests"
    },
    {
      "id": "WP-03",
      "title": "Training, competency and control measures",
      "owner_role": "Learning & Development Manager",
      "duration_quarters": 1,
      "deliverable": "Training curriculum, competency sign-off records and control measures to prevent deviation from standard handling"
    },
    {
      "id": "WP-04",
      "title": "Service level monitoring and performance governance",
      "owner_role": "Support Performance Manager",
      "duration_quarters": 1,
      "deliverable": "Governance dashboard and weekly governance report demonstrating progress toward 95% FCR and non-conformance alerts"
    },
    {
      "id": "WP-05",
      "title": "Pilot, measurement and continuous improvement loop",
      "owner_role": "Continuous Improvement Lead",
      "duration_quarters": 2,
      "deliverable": "Pilot results, measurement protocol, and plan for full roll-out with documented control actions and sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Readiness to remediate",
      "approver_role": "Head of Support",
      "criteria": "Acceptance of baseline report, confirmation of resources and sign-off on remediation approach"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Solution deployment approval",
      "approver_role": "Director of Operations",
      "criteria": "Successful pilot demonstrating improvement trajectory, tooling validated and control measures in place"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Full roll-out sign-off",
      "approver_role": "Chief Operating Officer",
      "criteria": "Measurement evidence showing sustained 95% FCR target met in pilot, governance dashboard live and no outstanding deviations"
    }
  ],
  "compliance_notes": [
    "All changes will follow documented change control and be recorded for audit trail",
    "Training records and sign-off are mandatory; non-conformance must be logged and addressed per quality management",
    "Data collection and reporting will comply with regulatory reporting standards and internal control requirements"
  ],
  "risks": [
    {
      "risk": "Insufficient accuracy of knowledge base leads to misrouting and unresolved support requests",
      "mitigation": "Validate knowledge base through end-user testing, maintain dual-checking controls and periodic reconciliation",
      "severity": "high"
    },
    {
      "risk": "Resistance to new tooling and process changes causing delayed adoption",
      "mitigation": "Engage stakeholders early, provide role-specific training, and require documented sign-off on competency before full roll-out",
      "severity": "medium"
    },
    {
      "risk": "Measurement discrepancies between source and reported FCR",
      "mitigation": "Define measurement protocol, use independent sample audits and reconcile data before gate review",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Consolidation of three overlapping tools into a single controlled platform within the next planning period",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Assessment and Requirements Consolidation",
      "owner_role": "Product Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Consolidated requirements document and gap analysis report for the three tools as a formal work package deliverable"
    },
    {
      "id": "WP-02",
      "title": "Design and Architecture Specification",
      "owner_role": "Enterprise Architect",
      "duration_quarters": 1,
      "deliverable": "Design and architecture specification for the consolidated platform with control, integration and compliance mappings"
    },
    {
      "id": "WP-03",
      "title": "Implementation and Migration Execution",
      "owner_role": "Implementation Manager",
      "duration_quarters": 2,
      "deliverable": "Executed migration of data and application logic to the consolidated platform with migration control records and validation deliverable"
    },
    {
      "id": "WP-04",
      "title": "Validation, Testing and Non-conformance Handling",
      "owner_role": "Quality Assurance Lead",
      "duration_quarters": 1,
      "deliverable": "Validation report, test evidence, and documented non-conformance handling procedures for gate review sign-off"
    },
    {
      "id": "WP-05",
      "title": "Operational Readiness and Training",
      "owner_role": "Operations Transition Manager",
      "duration_quarters": 1,
      "deliverable": "Operational runbook, training records, and transition sign-off package for operational control"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Initial Requirements Gate Review",
      "approver_role": "Head of Product",
      "criteria": "Approval of consolidated requirements, gap analysis, and acceptance of proposed scope; documented sign-off required to proceed"
    },
    {
      "gate": "G2",
      "name": "Design Gate Review",
      "approver_role": "Chief Architect",
      "criteria": "Design and architecture specification approved, control mappings validated, and mitigation plans for identified deviations; formal sign-off required"
    },
    {
      "gate": "G3",
      "name": "Pre-Implementation Gate Review",
      "approver_role": "Compliance and Risk Director",
      "criteria": "Migration plan, data retention policies, and compliance controls accepted; non-conformance handling procedures approved"
    },
    {
      "gate": "G4",
      "name": "Final Acceptance Gate Review",
      "approver_role": "Chief Operating Officer",
      "criteria": "Successful validation, test evidence, operational runbook, and training sign-off; formal sign-off to transition to BAU"
    }
  ],
  "compliance_notes": [
    "All activities will follow Meridian Industrial change control procedures and maintain auditable trail for each work package and gate review",
    "Data handling will comply with applicable regulatory records retention and privacy controls; deviations must be documented and approved through the gate review process"
  ],
  "risks": [
    {
      "risk": "Underestimated data complexity causing migration delays",
      "mitigation": "Perform early data assessment in WP-01, allocate dedicated migration resources in WP-03, and maintain rollback plan",
      "severity": "high"
    },
    {
      "risk": "Integration failures with downstream systems",
      "mitigation": "Define interface contracts in WP-02, conduct end-to-end integration tests in WP-03, and require sign-off at G2",
      "severity": "medium"
    },
    {
      "risk": "Operational disruption during cutover",
      "mitigation": "Execute cutover during approved window, maintain operational runbook in WP-05, and perform staged transitions with control checks",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "One planning period (four consecutive quarters) with gate reviews at the end of each major phase"
}

{
  "initiative": "Establish self-serve path to first value within 12 months",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define scope and success criteria for first value",
      "owner_role": "Product Strategy Lead",
      "duration_quarters": 1,
      "deliverable": "Scope document with measurable success criteria and control requirements"
    },
    {
      "id": "WP-02",
      "title": "Design minimum viable self-serve experience",
      "owner_role": "UX Architect",
      "duration_quarters": 2,
      "deliverable": "Design package and user journey map with acceptance criteria"
    },
    {
      "id": "WP-03",
      "title": "Build platform components and integrations",
      "owner_role": "Engineering Delivery Manager",
      "duration_quarters": 2,
      "deliverable": "Deployed platform components and integration test results"
    },
    {
      "id": "WP-04",
      "title": "Operational readiness and control setup",
      "owner_role": "Compliance & Operations Lead",
      "duration_quarters": 1,
      "deliverable": "Operational runbook, control checklist and non-conformance handling process"
    },
    {
      "id": "WP-05",
      "title": "Pilot execution and first value validation",
      "owner_role": "Program Manager",
      "duration_quarters": 1,
      "deliverable": "Pilot report demonstrating first value and deviation log"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1: Scope and Design Approval",
      "approver_role": "Head of Product",
      "criteria": "Formal sign-off on scope document, design package, and acceptance criteria; no open high-severity deviations"
    },
    {
      "gate": "G2",
      "name": "Gate 2: Build Readiness",
      "approver_role": "VP Engineering",
      "criteria": "Evidence of platform build completion, integration test results, and mitigation for any medium/high risks"
    },
    {
      "gate": "G3",
      "name": "Gate 3: Operational Control Approval",
      "approver_role": "Chief Compliance Officer",
      "criteria": "Runbook and control checklist approved; non-conformance handling process in place; compliance sign-off"
    },
    {
      "gate": "G4",
      "name": "Gate 4: Pilot Acceptance",
      "approver_role": "Executive Steering Committee",
      "criteria": "Pilot demonstrates first value within acceptance criteria, documented deviations addressed, and formal sign-off to proceed"
    }
  ],
  "compliance_notes": [
    "All activities will be documented to provide auditable traceability for each work package and gate review.",
    "Non-conformance handling must be defined and tested prior to pilot acceptance."
  ],
  "risks": [
    {
      "risk": "Scope creep delays first value realization",
      "mitigation": "Establish strict scope control in WP-01 with mandatory sign-off at G1; enforce measurable success criteria",
      "severity": "high"
    },
    {
      "risk": "Integration failures prevent first value demonstration",
      "mitigation": "Implement phased integration tests in WP-03 with rollback procedures and acceptance criteria in G2",
      "severity": "medium"
    },
    {
      "risk": "Operational controls inadequate leading to non-conformance during pilot",
      "mitigation": "Require compliance sign-off on runbook and control checklist in G3 and include corrective action plans",
      "severity": "medium"
    },
    {
      "risk": "Insufficient user adoption of self-serve path",
      "mitigation": "Include usage metrics and feedback channels in WP-02 and WP-05 with measurable acceptance criteria at G4",
      "severity": "low"
    }
  ],
  "timeline_horizon": "12 months from project start, aligned to quarterly gate reviews"
}

{
  "initiative": "Consolidate customer record systems to a single authoritative system",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Assess current customer record systems and data flows",
      "owner_role": "Systems Inventory Lead",
      "duration_quarters": 1,
      "deliverable": "Inventory report listing all systems holding customer records, data maps, and risk assessment"
    },
    {
      "id": "WP-02",
      "title": "Define target authoritative system and migration strategy",
      "owner_role": "Data Governance Manager",
      "duration_quarters": 1,
      "deliverable": "Target system specification, migration plan, and control requirements for data transfer"
    },
    {
      "id": "WP-03",
      "title": "Design and implement data migration and reconciliation",
      "owner_role": "Migration Program Lead",
      "duration_quarters": 2,
      "deliverable": "Completed migration runbooks, reconciliation reports, and non-conformance handling procedures"
    },
    {
      "id": "WP-04",
      "title": "Decommission legacy systems and perform remediation",
      "owner_role": "Infrastructure Decommissioning Lead",
      "duration_quarters": 1,
      "deliverable": "Decommission certificates, remediation log, and final sign-off on legacy removal"
    },
    {
      "id": "WP-05",
      "title": "Establish monitoring, access control and ongoing compliance controls",
      "owner_role": "Compliance and Access Control Lead",
      "duration_quarters": 1,
      "deliverable": "Monitoring dashboards, access control matrix, and control checklists for ongoing compliance"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate review: Assessment and Target Selection",
      "approver_role": "Chief Data Officer",
      "criteria": "Acceptable inventory completeness, target system selection documented, and risk register approved with mitigations"
    },
    {
      "gate": "G2",
      "name": "Gate review: Migration Design and Control Approval",
      "approver_role": "Head of Compliance",
      "criteria": "Migration plan, reconciliation criteria, and control requirements signed-off; non-conformance handling defined"
    },
    {
      "gate": "G3",
      "name": "Gate review: Decommission and Remediation Sign-off",
      "approver_role": "Chief Information Officer",
      "criteria": "Legacy decommission certificates issued, remediation actions closed or scheduled, and residual risks accepted"
    },
    {
      "gate": "G4",
      "name": "Gate review: Operational Readiness and Closure",
      "approver_role": "VP Operations",
      "criteria": "Monitoring in place, access controls validated, and formal sign-off on consolidated system deliverable"
    }
  ],
  "compliance_notes": [
    "All activities must follow corporate data control procedures and regulatory record retention policies",
    "Migration will be executed under change control with audit trail and non-conformance reporting",
    "Access to the authoritative system will be restricted to approved roles and subject to periodic access reviews"
  ],
  "risks": [
    {
      "risk": "Undiscovered customer records in legacy systems leading to data loss or compliance gaps",
      "mitigation": "Comprehensive discovery scanning, sample validation, and staged reconciliation with retention evidence",
      "severity": "high"
    },
    {
      "risk": "Data integrity issues during migration causing customer records to be incomplete or corrupted",
      "mitigation": "Parallel run with reconciliation controls, reconciliation sign-off criteria, and rollback procedures",
      "severity": "medium"
    },
    {
      "risk": "Resistance to change from business units delaying decommissioning and migration",
      "mitigation": "Stakeholder engagement plan, clear roles, and documented deviation handling with documented sign-off",
      "severity": "low"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Capacity Forecast Accuracy Improvement for Hiring Planning",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Establish Forecast Requirements and Control Framework",
      "owner_role": "Workforce Planning Lead",
      "duration_quarters": 1,
      "deliverable": "Documented forecast requirements, control framework and acceptance criteria for capacity forecast deliverable"
    },
    {
      "id": "WP-02",
      "title": "Data Integrity and Source System Remediation",
      "owner_role": "Data Governance Manager",
      "duration_quarters": 2,
      "deliverable": "Remediated data sources, validation routines and non-conformance handling procedure"
    },
    {
      "id": "WP-03",
      "title": "Forecast Model Development and Validation",
      "owner_role": "Business Analytics Lead",
      "duration_quarters": 2,
      "deliverable": "Validated forecasting model, validation report and model sign-off package"
    },
    {
      "id": "WP-04",
      "title": "Operational Integration and Tooling",
      "owner_role": "IT Integration Lead",
      "duration_quarters": 1,
      "deliverable": "Integrated forecast tooling, dashboard deliverable and user guide"
    },
    {
      "id": "WP-05",
      "title": "Governance, Training and Gate Review Preparation",
      "owner_role": "HR Planning Manager",
      "duration_quarters": 1,
      "deliverable": "Governance pack, training records, gate review checklist and final sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Requirements Gate Review",
      "approver_role": "Head of Workforce Planning",
      "criteria": "Approve requirements and control framework; no open deviations above minor; documented acceptance criteria for forecast deliverable"
    },
    {
      "gate": "G2",
      "name": "Technical Validation Gate Review",
      "approver_role": "Chief Data Officer",
      "criteria": "Validate data integrity, model accuracy thresholds met and non-conformance handling accepted; sign-off on model deliverable"
    },
    {
      "gate": "G3",
      "name": "Operational Readiness Gate Review",
      "approver_role": "VP of Operations",
      "criteria": "Confirm tooling integrated, dashboard usability verified and operational procedures accepted; readiness for hiring planning"
    },
    {
      "gate": "G4",
      "name": "Final Sign-off Gate Review",
      "approver_role": "Executive Steering Committee",
      "criteria": "Final sign-off on deliverable accuracy, control effectiveness and governance pack; authorization to use forecast for hiring decisions"
    }
  ],
  "compliance_notes": [
    "Maintain audit trail for all gate review records and sign-off artefacts",
    "All model changes require documented change control and non-conformance handling procedures",
    "Data handling must comply with corporate data protection and regulatory requirements"
  ],
  "risks": [
    {
      "risk": "Insufficient data quality undermines forecast accuracy",
      "mitigation": "Implement data remediation and validation routines, escalate persistent non-conformance to Data Governance Manager",
      "severity": "high"
    },
    {
      "risk": "Model complexity causes slow validation and delayed sign-off",
      "mitigation": "Define model scope in WP-01, allocate dedicated validation resources and schedule gate reviews at fixed intervals",
      "severity": "medium"
    },
    {
      "risk": "Operational teams do not adopt forecast tooling",
      "mitigation": "Deliver comprehensive training, include adoption metrics in gate criteria and require operational sign-off",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Increase review-process throughput by 40% without additional headcount",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Map current review workflow and identify bottlenecks",
      "owner_role": "Process Engineer Lead",
      "duration_quarters": 1,
      "deliverable": "Comprehensive workflow map and bottleneck analysis report as formal deliverable for gate review"
    },
    {
      "id": "WP-02",
      "title": "Define control improvements and standardisation of review tasks",
      "owner_role": "Quality Systems Manager",
      "duration_quarters": 1,
      "deliverable": "Standard work packages and control requirements document ready for sign-off"
    },
    {
      "id": "WP-03",
      "title": "Implement tooling and automation for repetitive reviews",
      "owner_role": "Engineering Automation Lead",
      "duration_quarters": 2,
      "deliverable": "Automated review tool deployed and integrated into workflow with audit trail"
    },
    {
      "id": "WP-04",
      "title": "Train review teams and enable cross-functional sign-off",
      "owner_role": "Training and Competency Manager",
      "duration_quarters": 1,
      "deliverable": "Training records, competency assessments and updated sign-off matrix"
    },
    {
      "id": "WP-05",
      "title": "Pilot changes and measure throughput improvement",
      "owner_role": "Operations Improvement Lead",
      "duration_quarters": 1,
      "deliverable": "Pilot report demonstrating measured throughput improvement and deviation log"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Initiation gate review",
      "approver_role": "Director of Manufacturing",
      "criteria": "Acceptance of workflow map, confirmed bottlenecks, and approval to proceed to control design; sign-off required"
    },
    {
      "gate": "G2",
      "name": "Design gate review",
      "approver_role": "Head of Quality",
      "criteria": "Approval of standard work, control requirements and tooling plan; risk assessment and non-conformance mitigation must be documented"
    },
    {
      "gate": "G3",
      "name": "Implementation gate review",
      "approver_role": "Chief Operating Officer",
      "criteria": "Evidence of automation deployment, training completion, and pilot plan; gate review sign-off to proceed to full roll-out"
    },
    {
      "gate": "G4",
      "name": "Closure and sustainment gate review",
      "approver_role": "VP Operations",
      "criteria": "Demonstrated >=40% throughput improvement in pilot, audit trail for tooling, and documented sustainment controls"
    }
  ],
  "compliance_notes": [
    "All changes will follow change control and be recorded in the configuration management system",
    "Training records and sign-off matrices will be retained to demonstrate competency and control",
    "Any deviation from approved standard work must be logged and escalated per non-conformance procedure"
  ],
  "risks": [
    {
      "risk": "Automation introduces errors that slow throughput",
      "mitigation": "Phased pilot with rollback plan, pre-deployment validation, and automated alert thresholds",
      "severity": "high"
    },
    {
      "risk": "Insufficient adoption of new standard work by review teams",
      "mitigation": "Mandatory training, competency assessments, and incentives tied to sign-off metrics",
      "severity": "medium"
    },
    {
      "risk": "Unrecorded non-conformance during pilot reduces measured throughput",
      "mitigation": "Independent audit of pilot data, immediate escalation of any findings, and corrective action plan",
      "severity": "high"
    }
  ],
  "timeline_horizon": "6 quarters from initiation with staged gate reviews at each major phase"
}

{
  "initiative": "Standardise Engineering-to-Operations Handoff for Repeatable Transition",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define Handoff Requirements and Acceptance Criteria",
      "owner_role": "Process Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Documented handoff requirements and acceptance criteria as formal work package deliverable for gate review"
    },
    {
      "id": "WP-02",
      "title": "Develop Handoff Package Template and Control Checklist",
      "owner_role": "Systems Integration Manager",
      "duration_quarters": 1,
      "deliverable": "Handoff package template, control checklist and non-conformance detection rules as deliverable for pilot"
    },
    {
      "id": "WP-03",
      "title": "Pilot Handoff Execution and Validation",
      "owner_role": "Operations Integration Lead",
      "duration_quarters": 1,
      "deliverable": "Pilot report with measured metrics, deviations logged, and recommended corrective actions"
    },
    {
      "id": "WP-04",
      "title": "Scale Handoff Process and Training Materials",
      "owner_role": "Training and Compliance Manager",
      "duration_quarters": 1,
      "deliverable": "Training records, updated procedures and control documents ready for full deployment"
    },
    {
      "id": "WP-05",
      "title": "Establish Monitoring, Auditing and Continuous Improvement Loop",
      "owner_role": "Quality Assurance Lead",
      "duration_quarters": 1,
      "deliverable": "Monitoring dashboard, audit plan and continuous improvement register as final deliverable"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Requirements and Template Approval",
      "approver_role": "Head of Engineering",
      "criteria": "Sign-off on handoff requirements, acceptance criteria and template; no unresolved deviations from engineering standards"
    },
    {
      "gate": "G2",
      "name": "Pilot Completion and Control Verification",
      "approver_role": "Director of Operations",
      "criteria": "Acceptance of pilot report demonstrating repeatable handoff with controlled checklist; any non-conformance documented and mitigations approved"
    },
    {
      "gate": "G3",
      "name": "Deployment and Training Sign-off",
      "approver_role": "Compliance and Training Director",
      "criteria": "Training completion evidence, updated procedures and control documents; formal sign-off to deploy to production"
    },
    {
      "gate": "G4",
      "name": "Sustainment and Closure",
      "approver_role": "Quality Assurance Director",
      "criteria": "Monitoring in place, audit plan active, and final closure sign-off confirming repeatable handoff deliverable"
    }
  ],
  "compliance_notes": [
    "All activities will be recorded in the project audit trail to support gate review evidence and control checks",
    "Any deviation from the defined handoff package must be logged as a non-conformance and routed through the corrective action process"
  ],
  "risks": [
    {
      "risk": "Inconsistent interpretation of acceptance criteria across engineering and operations",
      "mitigation": "Provide clear definitions in WP-01, require sign-off at G1 and include sample checklists in the template",
      "severity": "high"
    },
    {
      "risk": "Incomplete handoff packages leading to operational delays",
      "mitigation": "Enforce mandatory completion criteria in WP-02, monitor during pilot in WP-03 and close non-conformances promptly",
      "severity": "medium"
    },
    {
      "risk": "Insufficient training uptake causing process deviation",
      "mitigation": "Deliver role-specific training in WP-04, require evidence of completion at G3 and include refresher sessions in sustainment",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "5 quarters from initiation with gate reviews at quarter ends"
}

{
  "initiative": "Reduce new hire time-to-productivity by 50% through structured onboarding and controls",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define baseline metrics and target productivity",
      "owner_role": "HR Process Analyst",
      "duration_quarters": 1,
      "deliverable": "Baseline report with current time-to-productivity metrics, target 50% reduction, and measurement plan"
    },
    {
      "id": "WP-02",
      "title": "Design standardized onboarding curriculum and assessment",
      "owner_role": "Learning & Development Lead",
      "duration_quarters": 1,
      "deliverable": "Curriculum package, assessment tools, and control checklist for onboarding"
    },
    {
      "id": "WP-03",
      "title": "Pilot program with select cohorts and performance tracking",
      "owner_role": "Training Delivery Manager",
      "duration_quarters": 2,
      "deliverable": "Pilot report including measured productivity gains, deviation logs, and recommended adjustments"
    },
    {
      "id": "WP-04",
      "title": "Scale implementation and operationalize support",
      "owner_role": "Operations Integration Lead",
      "duration_quarters": 2,
      "deliverable": "Scaled rollout plan, training materials, and operational control documents"
    },
    {
      "id": "WP-05",
      "title": "Sustainment, monitoring and continuous improvement",
      "owner_role": "Continuous Improvement Manager",
      "duration_quarters": 2,
      "deliverable": "Monitoring dashboard, non-conformance handling process, and gate review schedule for sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Initiation gate review",
      "approver_role": "Head of HR",
      "criteria": "Baseline metrics defined, target set, and plan to pilot with measurable deliverable; sign-off required to proceed"
    },
    {
      "gate": "G2",
      "name": "Pilot gate review",
      "approver_role": "VP Operations",
      "criteria": "Pilot demonstrates >=40% reduction in time-to-productivity or documented corrective plan; approval to scale"
    },
    {
      "gate": "G3",
